sites.script:
// Opening another video inside YouTube's page (its own navigation) stalls when the ads were stripped from what it fetched: the player waits for an ad break that never comes, until a refresh. A full page load plays at once and stays ad-free, so while the blocker is on here, a jump to a different video becomes a real page load.
if (__DL_CFG.adBlock !== false && !__dlSiteMatch(__DL_CFG.allowed || [])) {
  var dlVideo = function (u) { try { var x = new URL(u, location.href); return x.pathname === '/watch' ? x.searchParams.get('v') : null; } catch (e) { return null; } };
  ['pushState', 'replaceState'].forEach(function (name) {
    var orig = history[name];
    history[name] = function (state, title, url) {
      var next = url == null ? null : dlVideo(url);
      if (next && next !== dlVideo(location.href)) { location[name === 'pushState' ? 'assign' : 'replace'](new URL(url, location.href).href); return; }
      return orig.apply(this, arguments);
    };
  });
}
